function applyBleeding(character,amount=1){if(!hasCondition(character,"morrendo"))return 0;const before=Math.max(0,Number(character.heart?.current)||0),damage=Math.min(before,Math.max(1,Number(amount)||1));character.heart.current=before-damage;updateLifeConditions(character);persist(character);return damage}

